; load address 0xC000, 16384 bytes. Names come from Fessor's reconstruction where known,
; otherwise sub_ (call target), loc_ (jump target), dat_ (data/variable reference).

; names of addresses in the other binaries
; Unrolled push run of the filled-circle scanline fill: the preceding self-patched jr jumps into it, so A is
; pushed as many times as needed; then the stack pointer is saved in ce2stack4 and ld hl,(ce2stack4) / dec hl
; leaves HL on the last byte written.

; (org removed: gaps.asm is INCLUDEd by commonxx.asm at &4000)

ScreenMem:
    call sub_C058
    ld l,l
    nop
    nop
    rst 0x18
    db "0",0xC0
    call sub_C058
    ret nz
    add a,l
    ld b,b
    ld a,(de)
    db 0x38,0xC0   ; was: jr c,0xBFD2
    call sub_C058
    nop
    ld b,b
    nop
    ret nz
    ld b,b
    ret nz
    call sub_C058
    nop
    ld (de),a
    ld b,b
    ex af,af'
    ld c,b
    ret nz
    call sub_C058
    nop
    djnz loc_C02A
loc_C02A:
    ld h,b
    ld d,b
    ret nz
