    jr loc_C02D
    db "loaderxxcommonx"
    ld a,b
    ld h,e
    ld l,a
    ld l,l
    ld l,l
    ld l,a
    ld l,(hl)
    ld (0x6C78),a
    ld h,c
    ld (hl),d
    ld h,a
