; Runs the galaxy seed twist (waggle_galaxy) four times
waggleGalaxy4Times:
    ld b,0x04
LAB_ram_ee02:
    push bc
    call waggle_galaxy
    pop bc
    djnz LAB_ram_ee02
    ret
; ZX Spectrum: squared_distance_to_cursor (&DFCE)
; Squared distance between the coordinate in A, B and the chart cursor: each axis difference is squared (one halved first, the chart has half
; the vertical scale) and summed. Out: HL = result, carry set on overflow.
squared_distance_to_cursor:
    push af
    ld a,(PresentPlanetX)
    call abs_difference
    ld d,a
    call mul_a_by_d
    pop bc
    push hl
    ld a,(PresentPlanetY)
    call abs_difference
    srl a
    ld d,a
    call mul_a_by_d
    pop de
    add hl,de
    ret
; ZX Spectrum: abs_difference (&DFEA)
; Out: A = |A - B|.
abs_difference:
    cp b
    jr nc,LAB_ram_ee2c
    ld c,b
    ld b,a
    ld a,c
LAB_ram_ee2c:
    sub b
    ret
; Turns the squared chart distance into a distance via a square root, or &FFFF on overflow
CalculateDistance:
    jr c,finalize_distance
    jr LAB_ram_ee35
; ZX Spectrum: finalize_distance (&DFF2)
finalize_distance:
    ld hl,0xFFFF
LAB_ram_ee35:
    ld a,h
    or l
    jr z,LAB_ram_ee41
    call approx_sqrt_16bit
    ld l,h
    ld h,0x00
    add hl,hl
    add hl,hl
LAB_ram_ee41:
    ld (0x3D5C),hl
    ret
; ZX Spectrum: mul_a_by_d (&E009)
; Out: HL = A * D (unsigned 8 x 8 bits).
mul_a_by_d:
    ld e,0x00
    ld b,0x08
    ld hl,0x0000
LAB_ram_ee4c:
    srl d
    rr e
    rl a
    jr nc,LAB_ram_ee55
    add hl,de
LAB_ram_ee55:
    djnz LAB_ram_ee4c
    ret
; ZX Spectrum: generate_system_name (&E01C)
; Builds a system's name in an 8-byte buffer from 3 or 4 pairs of letters (the fourth only when bit 6 of the seed byte is set), taken from the digram table.
name_planet:
    ld hl,0x3D41
    ld (0x3D67),hl
    ld b,0x08
clearTempname:
    ld (hl),0x00
    inc hl
    djnz clearTempname
    ld hl,(0x3D28)
    ld a,l
    and 0x40
    and a
    push af
    call AddDigram
    call AddDigram
    call AddDigram
    pop af
    jr z,waggle_galaxy
; Appends a two-letter digram of the system name from the seed, or twists the seed if the index is 0
AddDigram:
    ld hl,(0x3D2C)
    ld a,h
    and 0x1F
    and a
    jr z,waggle_galaxy
    ld hl,0x8DE2
    add a,a
    ld d,0x00
    ld e,a
    add hl,de
    ld a,(hl)
    inc hl
    push hl
    ld hl,(0x3D67)
    ld (hl),a
    inc hl
    ex de,hl
    pop hl
    ld a,(hl)
    ex de,hl
    cp 0x3F
    jr z,LAB_ram_ee9c
    ld (hl),a
    inc hl
LAB_ram_ee9c:
    ld (0x3D67),hl
; One step of the galaxy seed twist: shifts the three seed words along and adds the first two
waggle_galaxy:
    ld hl,(0x3D28)
    ld de,(0x3D2A)
    add hl,de
    ex de,hl
    ld hl,(0x3D2A)
    ld (0x3D28),hl
    ld hl,(0x3D2C)
    ld (0x3D2A),hl
    ld hl,(0x3D2A)
    add hl,de
    ld (0x3D2C),hl
    ret
; Copies the 8 bytes of the built planet name from &3D41 to &3D53
finalizePlanetName:
    ld bc,0x0008
    ld hl,0x3D41
    ld de,0x3D53
    ldir
    ret
; ZX Spectrum: generate_system_data (&E08C)
; Derives economy, government, tech level, population and productivity from the system's 6-byte seed (the BBC algorithm, bit arithmetic differs).
generatePlanetstats:
    ld hl,(0x3D28)
    ld (0x3D22),hl
    ld a,h
    ld (PresentPlanetY),a
    and 0x07
    ld (0x3D5E),a
    ld hl,(0x3D2A)
    ld (0x3D24),hl
    ld a,h
    ld (PresentPlanetX),a
    ld a,l
    srl a
    srl a
    srl a
    and 0x07
    ld (0x3D5F),a
    srl a
    jr nz,LAB_ram_eef9
    ld a,(0x3D5E)
    or 0x02
    ld (0x3D5E),a
LAB_ram_eef9:
    ld a,(0x3D5E)
    xor 0x07
    and a
    ld b,a
    ld a,h
    and 0x03
    add a,b
    ld b,a
    ld a,(0x3D5F)
    srl a
    adc a,b
    ld (0x3D60),a
    add a,a
    add a,a
    ld b,a
    ld a,(0x3D5F)
    ld c,a
    ld a,(0x3D5E)
    adc a,b
    adc a,c
    adc a,0x01
    ld (0x3D61),a
    ld a,(0x3D5E)
    xor 0x07
    adc a,0x03
    ld d,a
    ld a,(0x3D5F)
    adc a,0x04
    call mul_a_by_d
    ld a,(0x3D61)
    ld d,l
    call mul_a_by_d
    add hl,hl
    add hl,hl
    add hl,hl
    ld (0x3D62),hl
    ld hl,(0x3D2C)
    ld (0x3D26),hl
    ret
; Prints the distance to the selected system in light years, or nothing when it is zero
prLYDistance:
    ld hl,(0x3D5C)
    ld a,h
    or l
    ret z
    ld a,0xBF
    call anotherPrintWithToken3A
    ld a,0x04
    ld (0x3947),a
    ld hl,(0x3D5C)
    scf
    call todo_SomethingwithDigits
    call printStringFollowingByte
    db 0xC3
    jp placeCursor
; Copies the 6-byte galaxy seed from the saved seed (&3907) into the working seed (&3D28)
todoGenerateGalaxy:
    ld hl,0x3907
    ld de,0x3D28
    jr LAB_ram_ef77
; Copies the 6-byte working seed (&3D28) to the spare slot (&3D2E)
SUB_ram_ef69:
    ld hl,0x3D28
    ld de,0x3D2E
    jr LAB_ram_ef77
; Copies the 6-byte spare seed (&3D2E) back to the working seed (&3D28)
SUB_ram_ef71:
    ld hl,0x3D2E
    ld de,0x3D28
LAB_ram_ef77:
    ld bc,0x0006
    ldir
    ret
