; Splits a number in HL into decimal digits by repeated subtraction (10, 100, ...) for printing
todoDigitCalculation:
    ld b,0x01
    jr nc,LAB_ram_fe0e
    push hl
    and a
    ld de,0x000A
    sbc hl,de
    pop hl
    jr c,LAB_ram_fe32
LAB_ram_fe0e:
    and a
    ld de,0x000A
    call SBC_HLDE
    jr c,LAB_ram_fe33
    ld de,0x0064
    call SBC_HLDE
    jr c,LAB_ram_fe32
    ld de,0x03E8
    call SBC_HLDE
    jr c,LAB_ram_fe31
    ld de,0x2710
    call SBC_HLDE
LAB_ram_fe2d:
    jr c,LAB_ram_fe30
LAB_ram_fe2f:
    inc b
LAB_ram_fe30:
    inc b
LAB_ram_fe31:
    inc b
LAB_ram_fe32:
    inc b
LAB_ram_fe33:
    ld a,(0x3947)
    cp b
    ret z
    ret c
    sub b
    ld b,a
LAB_ram_fe3b:
    push bc
    ld a,(0x3946)
    and a
    jp z,LAB_ram_fe48
    ld a,0x20
    jp LAB_ram_fe4a
LAB_ram_fe48:
    ld a,0x30
LAB_ram_fe4a:
    call printString
    pop bc
    djnz LAB_ram_fe3b
    ret
; ZX Spectrum: cp_hl_de (&D3CE)
; Carry set if HL < DE; HL is unchanged (push, sbc, pop).
SBC_HLDE:
    push hl
    sbc hl,de
    pop hl
    ret
; ZX Spectrum: add_cash (&D3D3)
; Adds DE (tenths of a credit) to the remainder word; at 10000 it wraps and carries 1 into the thousands word. A second entry adds whole thousands.
getMoney:
    ld hl,(0x38DF)
    add hl,de
    ld (0x38DF),hl
    and a
    ld de,0x2710
    sbc hl,de
    ret c
    ld (0x38DF),hl
    ld de,0x0001
; Adds DE to the cash word at &38DD
AddDEtoMoney:
    ld hl,(0x38DD)
    add hl,de
    ld (0x38DD),hl
    ret
; Subtracts DE from the cash word at &38DD; carry set and no change if it would go negative
SbcDEfromMoney:
    ld hl,(0x38DD)
    sbc hl,de
    jr c,SetCarryflag
    ld (0x38DD),hl
    and a
    ret
SetCarryflag:
    scf
    ret
; ZX Spectrum: subtract_cash (&D3FD)
; Subtracts DE (tenths of a credit) from the cash, borrowing 1000 Cr from the thousands word when the remainder goes negative; carry set if there is not enough.
tryPayForGood:
    ld hl,(0x38DF)
    and a
    sbc hl,de
    jr nc,LAB_ram_fe9e
    ld hl,(0x38DD)
    ld a,l
    or h
    scf
    ret z
    dec hl
    ld (0x38DD),hl
    ld hl,0x2710
    and a
    sbc hl,de
    ld de,(0x38DF)
    add hl,de
LAB_ram_fe9e:
    ld (0x38DF),hl
    and a
    ret
useJumpTokens2:
    ld hl,Jumptokens2
    jr LAB_ram_feab
; ZX Spectrum: print_control_code (&D7B5)
; A = a control code 0-13 found inside a token: indexes the jump table and jumps to that handler.
useJumpTokens1:
    ld hl,Jumptokens1
LAB_ram_feab:
    ld d,0x00
    add a,a
    ld e,a
    add hl,de
    ld e,(hl)
    inc hl
    ld d,(hl)
    ex de,hl
    jp (hl)
