    call getMoneyinHLDE
    ld a,0xE2
    jr todojpPrintStringB
jpPrintCommanderName:
    ld hl,0x38CB
    jr jpPrintCleartext
; Entry that loads A=0 and joins the shared tail at &FFBC (chart/flight text helper, role unconfirmed)
SUB_ram_ff39:
    ld a,0x00
    jr LAB_ram_ffbc
jpprintFuelRange:
    ld a,0x69
    call anotherPrintWithToken3A
    IFDEF ENHANCED
